def match(orders):
    trades = []
    book = {'buy': [], 'sell': []}  # Each side: list of (arrival_time, price, qty, id)
    order_map = {}  # id -> (side, arrival_time, original_price, current_qty)
    arrival_time = 0

    def insert_order(side, id, price, qty, arrival):
        if side == 'buy':
            # Insert into buy book, sorted by: price desc, then arrival asc
            book['buy'].append((arrival, price, qty, id))
            book['buy'].sort(key=lambda x: (-x[1], x[0]))
        else:
            # Insert into sell book, sorted by: price asc, then arrival asc
            book['sell'].append((arrival, price, qty, id))
            book['sell'].sort(key=lambda x: (x[1], x[0]))
        order_map[id] = (side, arrival, price, qty)

    def find_order_in_book(side, id):
        for i, (arr, price, qty, oid) in enumerate(book[side]):
